insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bbed5acf-47e7-481b-a5b7-1d6b9eb91fd9', 'de', 'Vor dem Ansprechen taucht der Gedanke „Sie wird mich nicht mögen“ auf. Beste Reaktion?', '["Ihn als automatische Angst erkennen und trotzdem ansprechen", "Dagegen anargumentieren und Gründe aufzählen, warum sie dich mögen könnte", "Ihn als Motivation nutzen, an deiner Technik zu arbeiten", "Warten, bis der Gedanke vorbei ist, bevor du ansprichst"]'::jsonb, 'Der Gedanke ist automatische Angst, kein Stoppsignal. Sprich trotzdem an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7547b293-5e2d-432b-91d9-4b652d3472a7', 'de', 'Du spielst ein Gespräch im Kopf nach und baust daraus eine kritische Geschichte über dich. Was solltest du bemerken?', '["Die Geschichte ist ein handfester Beweis", "Das Nachspielen sofort abstellen", "Du musst jede vermeintliche Schwäche beheben", "Dein Kopf füllt Lücken mit Angst, nicht mit Fakten"]'::jsonb, 'Der Kopf füllt Lücken automatisch mit Angst. Wenn du das bemerkst, durchbrichst du das Muster.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5706755-0591-489f-9b13-9ec5811a5057', 'de', 'Nach dem Ansprechen sagt ein Gedanke: „Das klang peinlich.“ Was solltest du tun?', '["Ihn als Beweis nehmen und den Moment nachspielen", "Ihn dein Selbstbild bestimmen lassen", "Mit dem Gedanken diskutieren, bis er still ist", "Ihn als Hintergrundrauschen wahrnehmen, ohne ihm zu glauben"]'::jsonb, 'Du kannst nicht steuern, welche Gedanken auftauchen, aber du entscheidest, ob du ihnen glaubst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('70a9bde6-01ce-4b79-a9e2-97efa1252a1d', 'de', 'Was spiegelt eine Abfuhr meistens wider?', '["Wie wohl sich die andere Person gerade fühlt", "Fehler in deiner Art, es rüberzubringen", "Wenig Anziehung", "Soziales Versagen"]'::jsonb, 'Wer sich zurückzieht, schützt sich meistens selbst. Ein Urteil über dich ist das nicht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4792cc41-039e-460b-9a94-6f1fdb50ceb7', 'de', 'Wo zeigt sich echtes Selbstbewusstsein nach einer Abfuhr?', '["Darin, ganz bei dir zu bleiben, auch wenn du nicht gewollt wirst", "Darin, jeder Abfuhr aus dem Weg zu gehen", "Darin, von allen gemocht zu werden", "Darin, jeden Rückzieher wieder geradezubiegen"]'::jsonb, 'Selbstbewusstsein heißt, stabil zu bleiben, egal wie andere reagieren.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db69db01-07df-42b3-8e90-41a34457e803', 'de', 'Nach einem kurzen Gespräch verabschiedet sie sich höflich. Wovon solltest du ausgehen?', '["Du hast etwas Falsches gesagt und versagt", "Dein Wert wurde beurteilt und für zu gering befunden", "Sie hat auf ihr eigenes Wohlbefinden oder ihr Timing geachtet", "Du musst ihr hinterher, um es zu retten"]'::jsonb, 'Eine Abfuhr ist meistens Selbstschutz, kein Urteil über dich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e37e687b-c171-4e4a-b17d-9ae50f0a2b9f', 'de', 'Was schadet deinem Selbstbewusstsein nach schlechten Momenten wirklich?', '["Die Geschichte, die du dir immer wieder erzählst, nicht der Moment selbst", "Wie andere das Geschehene wahrgenommen und darauf reagiert haben", "Wie schlimm und peinlich die Situation tatsächlich war"]'::jsonb, 'Das Problem ist nicht der Moment, sondern die Erinnerung, die du immer wieder abspielst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43e16323-ce86-4e7f-9c28-27d04a6dcc33', 'de', 'Welche Macht hast du über vergangene Erfahrungen?', '["Sie komplett auszulöschen", "Jede künftige Peinlichkeit zu verhindern", "Andere dazu zu bringen, sie zu vergessen", "Selbst zu wählen, welche Bedeutung und Geschichte du mitnimmst"]'::jsonb, 'Deine Sichtweise schreibst du selbst. Schreib sie um, und du befreist dich vom negativen Rauschen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b74e3d6f-b4f5-4f7f-a9fe-edc477912533', 'de', 'Ein Typ wartet, bis er sich selbstbewusst fühlt, bevor er anspricht. Was ist das Problem?', '["Selbstbewusstsein entsteht durch Beweise. Warten schiebt es nur auf", "Er sollte erst an seinen inneren Überzeugungen arbeiten", "Er braucht mehr mentale Vorbereitung, bevor er handelt"]'::jsonb, 'Der Kopf vertraut greifbaren Beweisen aus dem Handeln. Erst kommt der Mut, dann das Selbstbewusstsein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8219bd4-82ca-488f-a68f-22ee4942c702', 'de', 'Woran erkennst du, dass dein Selbstbewusstsein wächst?', '["Du sagst etwas, obwohl du zögerst", "Du hältst Blickkontakt eine Sekunde länger, als es angenehm ist", "Du wartest, bis du dich bereit fühlst", "Du ziehst durch, obwohl Aufgeben leichter wäre"]'::jsonb, 'Beweise entstehen, wenn du trotz Unbehagen handelst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('12f0ca40-33ce-4e67-bffb-cfc678a28f97', 'de', 'Ein Typ spricht an, obwohl er zögert. Was registriert sein Gehirn?', '["„Ich hab’s trotzdem gemacht“ wird zum Beweis, dass er es kann", "„Ich hab die Angst überwunden“, was mit der Zeit mentale Stärke aufbaut", "„Ich war mutig“, was ein positives Selbstbild stärkt", "Alle oben genannten"]'::jsonb, 'Das alles hilft ihm und macht es wahrscheinlicher, dass er wieder anspricht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b0b79ba6-0f99-427a-8b41-59a2b41ccda1', 'de', 'Was sagt am besten voraus, ob sich deine sozialen Fähigkeiten verbessern?', '["Dranbleiben durch wiederholtes Üben", "Natürliches Talent und angeborene soziale Intelligenz", "Die Qualität von Anleitung und Mentoring"]'::jsonb, 'Fortschritt kommt von Übung, die sich über die Zeit aufsummiert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3e5a977-5717-4d10-aebd-1477b55d9977', 'de', 'Zwei Typen haben beide eine peinliche Begegnung. Einer versucht es wieder, der andere hört auf. Was ist der Unterschied?', '["Der eine dachte, ihm fehlt Übung, der andere dachte, ihm fehlt das Talent", "Der eine ist von Natur aus sozial begabt, der andere nicht", "Der eine hatte bessere Techniken und Grundlagen"]'::jsonb, 'Der Unterschied liegt in dem Schluss, den sie gezogen haben, nicht in der Begegnung selbst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f9d8c142-995d-43f7-81fe-a5b493c6b7af', 'de', 'Welche Überzeugungen zeigen Wachstumsdenken?', '["Fähigkeiten lassen sich verbessern", "Anstrengung führt irgendwohin", "Scheitern bestimmt, was du kannst"]'::jsonb, 'Wer glaubt, dass seine Fähigkeiten wachsen können, lernt weiter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b35fc5b-fbe7-4df2-9a70-b1ba3a8b77b9', 'de', 'Warum wird die Angst mit der Zeit größer, wenn du nicht handelst?', '["Das Selbstbewusstsein schwindet", "Die Erinnerung übertreibt", "Das Risiko fühlt sich größer an", "Der Körper lernt, dass Vermeiden sicher ist"]'::jsonb, 'Jedes Ausweichen verstärkt die Angstreaktion deines Körpers.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ba6899a-7c48-43f0-9751-4de815468a09', 'de', 'Ein Typ will warten, bis die Angst nachlässt, bevor er anspricht. Was ist das Problem?', '["Er verpasst den besten Moment, ein Gespräch anzufangen", "Die Angst kommt beim nächsten Versuch stärker zurück", "Er lässt seine Nervosität entscheiden", "Angst löst sich durch Handeln auf, nicht durch Warten"]'::jsonb, 'Angst verschwindet nicht durch Nachdenken oder Zeit. Sie löst sich auf, wenn du dich bewegst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f9aab5f-516e-467e-859b-ddaecdf461cd', 'de', 'Was passiert, wenn du trotz Angst ansprichst?', '["Der befürchtete Schmerz tritt immer ein", "Selbstbewusstsein setzt voraus, dass du vorher keine Angst hast", "Die Angst wird durch Konfrontation stärker", "Dein Nervensystem lernt, dass die Bedrohung falscher Alarm war"]'::jsonb, 'Handeln widerlegt die Befürchtung und dämpft künftige Reaktionen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ce08bb8-9bb3-4d2e-b08c-7b62c8593bb1', 'de', 'Warum fühlt es sich intensiver an, gesehen zu werden, als es eigentlich ist?', '["Die Leute schauen tatsächlich genau hin", "Man wird ständig beurteilt", "Der Kopf überschätzt, wie sehr man im Mittelpunkt steht", "Die sozialen Regeln sind streng"]'::jsonb, 'Der Kopf überschätzt, wie viel andere mitbekommen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ef57991-7795-4349-9a51-3c0db95233c6', 'de', 'In einer Gruppe richtet sich plötzlich die Aufmerksamkeit auf dich. Was solltest du tun?', '["Entspannt bleiben und ganz normal weitermachen", "Dich innerlich zurückziehen und dich selbst beobachten", "Selbstbewusstsein vorspielen, um die Anspannung zu verstecken", "Schnell aus dem Gespräch verschwinden"]'::jsonb, 'Gelassenheit entsteht, wenn du dich nicht dagegen wehrst, gesehen zu werden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39115a96-71ac-4675-991c-cb9189cd877a', 'de', 'Wie wirkt sich Selbstbeobachtung auf deine Präsenz aus?', '["Sie fördert echte Verbindung", "Sie macht aus Ausdruck eine Vorstellung", "Sie lenkt die Aufmerksamkeit nach innen statt nach außen"]'::jsonb, 'Selbstbeobachtung untergräbt natürliche Gelassenheit und Lockerheit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28ccfdfd-13b7-4bf5-9d16-e2ade47fa571', 'de', 'Was signalisiert flache Atmung deinem Körper?', '["Sicherheit", "Bedrohung", "Konzentration", "Selbstbewusstsein"]'::jsonb, 'Schnelles Atmen signalisiert deinem Körper Gefahr. Atme langsamer, um dich zu beruhigen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('784400be-2ea4-4606-85a5-fb25457e3b9c', 'de', 'Der Druck steigt, und bevor du etwas sagst, rasen deine Gedanken. Was würde helfen?', '["Die Worte im Kopf durchgehen", "Der Situation ausweichen, bis du ruhig bist", "Einmal ruhig einatmen und kontrolliert ausatmen"]'::jsonb, 'Wenn du auf deinen Atem achtest, erinnerst du deinen Körper daran, dass du die Kontrolle hast.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a7a2960-2b38-4259-9599-598cc15e9937', 'de', 'Warum reduziert langsames Atmen die Angst so wirksam?', '["Es widerlegt negative Gedanken direkt", "Es signalisiert deinem Nervensystem Sicherheit", "Es senkt den Puls und macht den Kopf frei"]'::jsonb, 'Wenn du langsamer ausatmest, merkt dein Nervensystem, dass keine Bedrohung da ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('013f4dc3-e950-4940-9fab-7657d9decb9b', 'de', 'Wie unterbricht Erdung kreisende Gedanken?', '["Indem sie die Bedeutung umdeutet", "Indem sie die Aufmerksamkeit auf Körperempfindungen lenkt", "Indem sie die Konzentration steigert", "Indem sie Gefühle unterdrückt"]'::jsonb, 'Erdung wirkt, indem sie die Aufmerksamkeit aus dem Kopf in den Körper holt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('81883b1d-a00d-4283-b3fc-38c0192aaff9', 'de', 'Wo sitzt Nervosität, und wie hilft Erdung?', '["Nervosität sitzt in alten Verletzungen. Erdung schafft neue Erfahrungen", "Nervosität sitzt im Körper. Erdung löst körperliche Anspannung", "Nervosität sitzt in Gedanken an die Zukunft. Erdung holt dich zurück ins Hier und Jetzt"]'::jsonb, 'Nervosität sitzt in Gedanken an die Zukunft. Erdung holt deine Aufmerksamkeit zurück in deinen Körper, ins Jetzt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b700e82d-a04f-4ae2-af7e-9af63595b855', 'de', 'Welche Erdungsübungen helfen gegen Nervosität?', '["Deine Füße auf dem Boden spüren", "Wahrnehmen, wie sich dein Atem bewegt", "Sätze fürs Gespräch planen", "Die Schultern lockern"]'::jsonb, 'Erdung wirkt, indem sie die Aufmerksamkeit aus dem Kopf in den Körper holt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cdb8cfc-39c3-4aee-8e46-064ef4dd4976', 'de', 'Beim Ansprechen fühlst du dich im Stehen steif. Was hilft am meisten?', '["Dich nach vorn lehnen", "Langsamer sprechen", "Witze machen", "Schultern und Atem lockern"]'::jsonb, 'Wenn du zuerst den Körper lockerst, kommt deine natürliche Präsenz im Gespräch zurück.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35629852-7dc2-4adf-8383-df72ab56b0fb', 'de', 'Wie hängen Körpersprache und Vertrauen zusammen?', '["Einheitliche Körpersprache baut mit der Zeit Vertrauen auf", "Menschen vertrauen dem, was sie sehen, mehr als dem, was sie hören", "Vertrauenswürdige Menschen haben von Natur aus eine offene, entspannte Körpersprache"]'::jsonb, 'Menschen reagieren auf nonverbale Signale, bevor sie Erklärungen zuhören.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('be052099-dc33-4516-be7b-fb7e8a574364', 'de', 'Warum spricht die Körpersprache vor den Worten?', '["Das Gehirn prüft Bewegung und Haltung zuerst auf Sicherheit", "Menschen verarbeiten nonverbale Signale schneller als Worte", "Wenn Körper und Worte nicht zusammenpassen, spürt man einen Bruch", "Worte überstimmen körperliche Signale immer"]'::jsonb, 'Nonverbale Signale werden instinktiv verarbeitet, noch bevor die Logik einsetzt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('32686574-8a7a-4a9b-8887-1bf18793907c', 'de', 'Wie reagieren Menschen tatsächlich auf deinen Tonfall?', '["Klingst du angespannt, werden sie angespannt. Klingst du entspannt, entspannen sie sich", "Sie nehmen deinen Gefühlszustand bewusst wahr und bewerten ihn", "Stimmmuster lösen Spiegelneuronen aus, die Empathie erzeugen"]'::jsonb, 'Menschen spiegeln unbewusst die Energie deiner Stimme. Bleib ruhig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('82c30e7d-5adc-41dc-afc4-5569d6e8fb80', 'de', 'Welche Sprechweisen helfen anderen, sich wohlzufühlen?', '["Langsameres Tempo", "Beim Ausatmen sprechen", "Stille schnell füllen", "Gleichmäßige Lautstärke"]'::jsonb, 'Ein ruhiges Tempo und ruhiger Atem lassen deine Stimme sicher wirken, und man hört dir gern zu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cdfce0f-0fe8-4f05-b355-7b070e7383bd', 'de', 'Warum wirkt eine ruhige Stimme stärker als eine laute?', '["Sie erzwingt Aufmerksamkeit durch Lautstärke", "Sie signalisiert unbewusst Sicherheit und Leichtigkeit", "Sie bringt Menschen ohne Druck zum Zuhören", "Sie verleiht Gewicht und einen entspannten Rhythmus"]'::jsonb, 'Ein ruhiger Ton zieht Menschen an, weil er Stabilität ausstrahlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6cd4ab05-6a0e-4e05-9ef2-09775c5c9496', 'de', 'Warum kann wenig Energie andere abstoßen?', '["Es fühlt sich unangenehm an, sie zu spiegeln", "Sie wirkt arrogant", "Sie wirkt desinteressiert"]'::jsonb, 'Menschen meiden instinktiv Stimmungen, die sich schwer anfühlen. Halt deine Energie positiv.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e40cadb9-6906-42bf-b334-b269e634ab6e', 'de', 'Wie kannst du deine Energie vor dem Ansprechen verbessern?', '["Dich kurz bewegen, lächeln, dir selbst Mut zusprechen", "Die Situation länger analysieren", "Warten, bis das Selbstbewusstsein kommt", "Dich zurückziehen, um Anspannung zu vermeiden"]'::jsonb, 'Bewegung verändert schnell deinen Zustand und hebt deine Energie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d028ed4f-fd88-4a7c-8aab-17f7a78c6a9a', 'de', 'Wie wirkt sich positive Energie beim Ansprechen aus?', '["Sie zieht Menschen unbewusst an", "Sie lädt ganz natürlich zum Gespräch ein", "Sie setzt ein perfektes Aussehen voraus"]'::jsonb, 'Gute Energie bringt Menschen dazu, sich dir zuzuwenden, und in deiner Nähe fühlen sie sich wohler.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55639c7a-b396-4a1c-ae26-431442cfe270', 'de', 'Was signalisiert ein echtes Lächeln zuerst?', '["Anziehung", "Selbstbewusstsein", "Sicherheit und Wärme", "Verspieltheit"]'::jsonb, 'Ein Lächeln wird sofort als sicher gelesen. Das hilft dir, noch bevor ein Wort fällt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfa95ebd-1b35-41c8-8a50-fbcb06fee6aa', 'de', 'Warum baut Lächeln soziale Anspannung ab?', '["Es lenkt die Aufmerksamkeit ab", "Es löst positive Gefühle aus", "Es versteckt Nervosität"]'::jsonb, 'Wenn du lächelst, registrieren beide Gehirne etwas Positives, bevor ein Wort fällt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2886592f-4bba-4b7d-bcfc-6547f1eb778e', 'de', 'Wie löst ein echtes Lächeln bei beiden eine positive Reaktion aus?', '["Es signalisiert dem Nervensystem Bedrohung", "Es hebt neurologisch die Stimmung und senkt Stress", "Das Gehirn spiegelt das positive Gefühl unbewusst"]'::jsonb, 'Lächeln löst bei beiden positive Gefühle aus, noch bevor das Gespräch beginnt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2c9f06f7-4cf4-45f9-80cd-7c8fcac8c28c', 'de', 'Warum untergräbt es dein Selbstbewusstsein, wenn du auf Bestätigung angewiesen bist?', '["Es erzeugt Druck", "Es schränkt dich im Ausdruck ein", "Es signalisiert Selbstzweifel", "Es schwächt deine Grenzen"]'::jsonb, 'Wer Bestätigung braucht, zeigt, dass er sie sich selbst nicht geben kann.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bd56cd8-1f4f-4678-8dce-d3e92a3e8932', 'de', 'Sie äußert eine Meinung, die du nicht teilst. Womit vermeidest du, um ihre Zustimmung zu werben?', '["Sofort zustimmen, damit die Harmonie bleibt", "Höflich deine andere Sicht sagen, ohne dich zu entschuldigen", "Deine Meinung an ihre anpassen", "Schweigen, um Streit zu vermeiden"]'::jsonb, 'Wenn du ruhig bei deiner Haltung bleibst, zeigst du, dass du mit dir im Reinen bist, ohne bedürftig zu wirken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3fe6a5a2-4f72-4f9a-9d46-3a48ef587e96', 'de', 'Warum zerstört die Suche nach Bestätigung Anziehung?', '["Sie wirkt verzweifelt", "Sie knüpft deinen Wert daran, ob sie dich akzeptiert", "Sie macht dich unecht", "Sie garantiert immer eine tiefere Verbindung"]'::jsonb, 'Die Suche nach Bestätigung zeigt Selbstzweifel. Selbstakzeptanz zeigt Stärke.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e562de05-8b81-429d-b188-fbe14cf83db2', 'de', 'Ein Typ ist nach Monaten des Übens immer noch nervös. Woran sollte er sich messen?', '["Ob andere bei ähnlich viel Übung schneller vorankommen", "Ob er jetzt Dinge kann, die er vorher nicht konnte", "Wie er im Vergleich zu Männern dasteht, die von Natur aus selbstbewusst sind"]'::jsonb, 'Der einzige sinnvolle Maßstab ist, ob du besser bist als vorher.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('586652d7-39f3-41aa-9a2f-cb693ae30050', 'de', 'Warum schadet es deiner Entwicklung, dich mit anderen zu vergleichen?', '["Du kennst weder ihren Ausgangspunkt noch wie viel sie geübt haben noch ihre ganze Geschichte", "Es weckt unrealistische Erwartungen, die garantiert enttäuscht werden", "Du vergleichst dein Innenleben mit den sichtbaren Ergebnissen anderer, und das ist nicht fair"]'::jsonb, 'Du siehst ihre Ergebnisse, ohne ihren Ausgangspunkt oder ihre Geschichte zu kennen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9250aace-fa4f-4d66-95e4-793349439200', 'de', 'Was macht das Ansprechen leichter?', '["Das Ergebnis nicht bestimmen lassen, wer du bist", "Abfuhren als normalen Teil des Prozesses akzeptieren", "Beides"]'::jsonb, 'Wenn das Ergebnis nicht über deinen Wert entscheidet, ist Ansprechen weniger einschüchternd.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53bacb30-3d41-4c17-a18d-8c00b9bc1398', 'de', 'Was heißt es, in sozialen Situationen unabhängig vom Ergebnis zu sein?', '["Dein inneres Gleichgewicht halten, egal wie die andere Person reagiert", "Dass dir das Ergebnis völlig egal ist", "Jedes Mal ein positives Ergebnis erzwingen", "Begegnungen meiden, um auf Nummer sicher zu gehen"]'::jsonb, 'Wenn deine Stimmung stabil bleibt, egal wie die Reaktion ausfällt, hast du wieder die Kontrolle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('83794883-664e-42e0-89fa-abc8d0f95334', 'de', 'Was bedeutet es wirklich, unabhängig vom Ergebnis zu sein?', '["Dass dir Ergebnis und Erfolg einer Begegnung völlig egal sind", "Dein inneres Gleichgewicht halten, egal wie eine Begegnung läuft", "Dein Selbstwert und deine Stimmung hängen nicht an bestimmten Ergebnissen"]'::jsonb, 'Das Ergebnis ist dir nicht egal, aber es bestimmt nicht mehr, wie du dich fühlst oder verhältst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d1a173-8185-476b-ba48-a86f79e52a48', 'de', 'Was ist der Schlüssel, um gut mit positiven Reaktionen umzugehen?', '["Dich mehr anstrengen, um ihre Aufmerksamkeit zu halten", "Deine Energie runterfahren, um keinen Druck zu machen", "Den Moment kontrollieren, damit du nichts verlierst", "Genau die Version von dir bleiben, die ihr Interesse geweckt hat"]'::jsonb, 'Die Version von dir, die die Anziehung geweckt hat, reicht schon. Du musst nichts draufsetzen oder vorspielen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b61bcf4-54dc-4de9-8ba8-813071e2e979', 'de', 'Die Stimmung ist super, und sie lehnt sich zu dir. Dein Kopf fängt an, das „Was jetzt?“ zu planen. Was solltest du tun?', '["Zurück ins Hier und Jetzt kommen, ohne zu kontrollieren", "Die Gedanken übernehmen und planen lassen", "Schnell einen Schritt weitergehen, um es auszunutzen", "Dich von der positiven Energie zurückziehen"]'::jsonb, 'Wenn es gut läuft, ist deine Aufgabe, den Rhythmus zu halten, nicht das Ergebnis zu steuern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b5dc6ef-1cda-498e-932d-4939839666ad', 'de', 'Warum können positive Reaktionen dich aus dem Gleichgewicht bringen?', '["Sie lösen aus einem Mangeldenken heraus die Suche nach Bestätigung aus", "Sie wecken die Angst, das gute Gefühl zu verlieren", "Sie verlangen keine Änderung deines Verhaltens", "Sie können Druck erzeugen, die Situation auszunutzen und zu kontrollieren"]'::jsonb, 'Mit positiven Signalen gibt es plötzlich etwas zu verlieren. Verfall nicht darin, das Ergebnis absichern zu wollen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5956bc0c-e67e-486c-9121-0d4f3f555035', 'de', 'Was verändert Fitness vor allem, noch bevor andere deinen Körper bemerken?', '["Dein Trainingswissen und deine Disziplin", "Dein Selbstbild und dein inneres Selbstbewusstsein", "Deine Fähigkeit, Aufmerksamkeit auf dich zu ziehen", "Deine Gesprächsfähigkeiten und deinen Charme"]'::jsonb, 'Selbstbewusstsein wächst, wenn sich zuerst dein inneres Bild von dir verbessert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ec8b2af-94c5-4b1c-a704-f2bd3e950b20', 'de', 'Wie hilft Fitness, dein Selbstbewusstsein zu steigern?', '["Sie ist ein körperlicher Beweis, dass du dich selbst ernst nimmst", "Sie macht dich für Frauen sichtbar attraktiv", "Sie lehrt Disziplin, die sich aufs Dating überträgt", "Sie gibt dir Status in sozialen Situationen"]'::jsonb, 'Fitness verändert zuerst dein Selbstbild, und dadurch sprichst du eher jemanden an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0c9fead-d08c-463e-82b3-6acbc68aa42b', 'de', 'Wodurch entsteht der Schub an Selbstbewusstsein durch gute Fitness?', '["Du traust deinem Körper mehr zu", "Du siehst im Spiegel einen Körper, den du respektierst", "Du beobachtest dich in sozialen Situationen weniger selbst", "Du bekommst Komplimente von anderen"]'::jsonb, 'Selbstrespekt prägt dein Verhalten lange bevor Bestätigung von außen eine Rolle spielt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('941578b4-3efd-48fd-bb43-567d6cc34570', 'de', 'Wie wirkt sich mangelnde Körperpflege auf den ersten Eindruck aus?', '["Frauen erwarten mehr Mühe", "Sie signalisiert niedrigen Status", "Sie sorgt für frühes Zögern, bevor Anziehung entstehen kann"]'::jsonb, 'Erste optische Eindrücke prägen Wohlgefühl und Interesse, bevor das Gespräch beginnt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('320c1b55-513d-40ef-8b8a-5575836c5e6c', 'de', 'Was ist die wichtigste innere Wirkung von gepflegtem Aussehen?', '["Bestätigung von außen durch Komplimente", "Selbstbewusstsein durch Willenskraft erzwingen", "Eine drastische Veränderung deines Aussehens", "Dich ohne Anstrengung gepflegt und souverän fühlen"]'::jsonb, 'Körperpflege verändert dein Selbstbild, und dadurch sprichst du eher jemanden an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8f3b672-a516-497b-889c-0bb6535c7859', 'de', 'Welche Vorteile hat Körperpflege?', '["Ein besserer erster Eindruck", "Weniger innere Hürden, sodass sich dein Verhalten natürlich anfühlt", "Sie zeigt möglichen Partnerinnen deinen Selbstrespekt", "Sie verschafft dir einen Vorteil gegenüber weniger gepflegten Männern"]'::jsonb, 'Ein besserer erster Eindruck, freieres Verhalten und sichtbarer Selbstrespekt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
